import Vue from 'vue'
import BranchOneDialog from '@/views/supervision/agreement/xy/components/BranchOneDialog.vue'

let unionBankBranchOpening = false

/**
 * 寮€鎴风綉鐐?/ 鑱旇閫夋嫨锛堝叧閿瓧锛屽彲閫夊乏渚ч摱琛屾爲锛?
 * 浣跨敤 BranchOneDialog + zs-select-dialog 瀹炵幇锛屽澶栨彁渚涘嚱鏁板紡 Promise API
 */
export function openUnionBankBranchSelect(vm, options = {}) {
  if (unionBankBranchOpening) {
    return Promise.reject('already_open')
  }

  const active = document.activeElement
  if (active && typeof active.blur === 'function') {
    active.blur()
  }

  return new Promise((resolve, reject) => {
    unionBankBranchOpening = true

    const props = {
      visible: true,
      title: options.title || '閫夋嫨寮€鎴风綉鐐?,
      workBankId: options.workBankId,
      url: options.url || '/system/unionBank/page',
      bankName: options.bankName,
      bankCode: options.bankCode,
      showTree: options.showTree ?? false,
      showTable: options.showTable ?? true,
      tableScroll: options.tableScroll ?? false,
      outQuery: options.outQuery || options.filterParams || {}
    }

    const instance = new (Vue.extend(BranchOneDialog))({
      parent: vm,
      propsData: props,
      store: vm.$store,
      router: vm.$router
    })

    const releaseOpeningLock = () => {
      unionBankBranchOpening = false
    }

    const cleanup = () => {
      releaseOpeningLock()
      try {
        if (instance && !instance._isDestroyed) {
          instance.$destroy()
        }
        if (instance.$el?.parentNode === document.body) {
          document.body.removeChild(instance.$el)
        }
      } catch (e) {
        console.warn('openUnionBankBranchSelect cleanup:', e)
      }
    }

    instance.$on('setData', (row) => {
      cleanup()
      resolve(row)
    })
    instance.$on('update:visible', (visible) => {
      if (!visible) {
        cleanup()
        reject('cancel')
      }
    })

    instance.$mount()
    document.body.appendChild(instance.$el)
  })
}
"}]

