if (StrUtil.isBlank(queryDto.getBankName()) && queryDto.getWorkBankId() != null) {
    try {
        JsonResult<String> bankNameResult = remoteBankBranchService.getBankNameByBankId(queryDto.getWorkBankId());
        if (bankNameResult != null && bankNameResult.getData() != null
                && StrUtil.isNotBlank(bankNameResult.getData())) {
            queryWrapper.like(SysUnionBank::getBankName, bankNameResult.getData());
        }
    } catch (Exception e) {
        log.warn("按承办银行过滤网点时反查承办银行名称失败, workBankId={}", queryDto.getWorkBankId(), e);
    }
}

