/**
 * 按承办银行过滤网点：承办银行ID。
 * 前端选择承办银行后传该字段，后端反查其名称作为 bankName 过滤条件。
 * 注意：不能直接用承办银行的 bankNum 当 bankCode，它并非联行表的大行代码。
 */
@Schema(description = "承办银行ID（用于按承办银行过滤网点）")
private Long workBankId;

/**
 * 是否主行
 */
@Schema(description = "是否主行")
private String isMainLine;

queryWrapper
        .like(StrUtil.isNotBlank(queryDto.getIsMainLine()), SysUnionBank::getIsMainLine, queryDto.getIsMainLine())
        .in(CollUtil.isNotEmpty(queryDto.getBankNames()), SysUnionBank::getBankName, queryDto.getBankNames());
// 按承办银行过滤网点：前端往往只传承办银行ID（workBankId），其 bankNum 并非联行大行代码，
// 不能直接当 bankCode 用。这里反查承办银行名称，作为 bankName 过滤条件，
// 与前端已传的 bankName 二选一，避免返回全部网点（bug 6164）。
if (StrUtil.isBlank(queryDto.getBankName()) && queryDto.getWorkBankId() != null) {
    try {
        JsonResult<String> bankNameResult = remoteBankBranchService.getBankNameByBankId(queryDto.getWorkBankId());
        if (bankNameResult != null && bankNameResult.getData() != null
                && StrUtil.isNotBlank(bankNameResult.getData())) {
            queryWrapper.like(SysUnionBank::getBankName, bankNameResult.getData());
        }
    } catch (Exception e) {
        log.warn("按承办银行过滤网点时反查承办银行名称失败, workBankId={}", queryDto.getWorkBankId(), e);
    }
}

@Autowired
private BankBranchService bankBranchService;

@Autowired
private WorkBankService workBankService;

/**
 * 根据承办银行ID查询网点联行号
 */
@Operation(description = "根据承办银行ID查询网点联行号")
@Override
public JsonResult<String> getUnionBankCodeByBankId(Long workBankId) {
    return JsonResult.success(bankBranchService.getUnionBankCodeByWorkBankId(workBankId));
}

/**
 * 根据承办银行ID查询承办银行名称（用于按承办银行过滤联行网点）
 */
@Operation(description = "根据承办银行ID查询承办银行名称")
@Override
public JsonResult<String> getBankNameByBankId(Long workBankId) {
    if (workBankId == null) {
        return JsonResult.success(null);
    }
    WorkBankVo vo = workBankService.getByWorkBankId(workBankId);
    return JsonResult.success(vo == null ? null : vo.getBankName());
}

